import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{A as t,C as n,M as r,N as i,O as a,P as o,S as s,T as c,b as l,k as u,l as d,n as f,o as p,t as m,x as h}from"./shared-JA1PGxXr.js";var g=e();function _({module:e}){return(0,g.jsxs)(i,{children:[(0,g.jsx)(r,{chip:e??`Глава 3 · HTTP и Planner API`,title:`Методы и изменение задачи`,intro:`Свяжем намерение клиента с тем, что происходит с задачей, и отделим это намерение от ответа сервера.`}),(0,g.jsxs)(o,{number:`00`,title:`От ответа возвращаемся к намерению`,children:[(0,g.jsx)(a,{children:`В прошлом занятии мы разбирали, что сервер вернул: статус, тело ответа и его формат. Теперь посмотрим на начало обмена: какое действие клиент просит выполнить?`}),(0,g.jsx)(`p`,{children:`Названия методов могли встречаться раньше, но это ещё не значит, что мы умеем выбирать их самостоятельно. Начнём с простого вопроса: клиент только читает данные или просит изменить задачу? Если request, response, status или body пока путаются, вернитесь к предыдущей опоре: request — просьба клиента, response — ответ сервера, status — краткий результат, body — данные ответа.`}),(0,g.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Перед началом проверим на новом примере: где просьба клиента, где ответ сервера, и что показывают status и body.`},{title:`Новый вопрос`,description:`Как метод показывает, что клиент хочет прочитать, создать, заменить, изменить частично или удалить?`},{title:`Результат`,description:`Мы объясняем выбор GET, POST, PUT, PATCH или DELETE для знакомого действия Planner.`}]}),(0,g.jsx)(`p`,{children:`Метод относится к запросу, а статус относится к ответу. Это разные части одной договорённости: клиент сообщает намерение, сервер обрабатывает запрос и возвращает результат. Мы не запускаем сервер и не меняем Planner. Сначала разберём сами намерения, а затем передадим готовую таблицу следующему занятию, где к методу добавится адрес.`})]}),(0,g.jsxs)(o,{number:`01`,title:`Метод сообщает, чего просит клиент`,children:[(0,g.jsx)(a,{children:`В request метод называет тип операции. Он помогает серверу понять смысл обращения, но сам по себе не выбирает задачу и не исполняет код.`}),(0,g.jsx)(`p`,{children:`HTTP, то есть протокол обмена сообщениями между клиентом и сервером, задаёт набор методов. В Planner мы используем GET для чтения, POST для создания, PUT для полной замены изменяемых полей, PATCH для передачи отдельных изменений и DELETE для удаления. Это договор нашего API: одинаковое имя в другой системе может быть связано с иной прикладной логикой.`}),(0,g.jsx)(`p`,{children:`Метод не является именем функции Python, командой CLI или названием файла. Сервер сопоставляет части запроса со своими маршрутами и уже там вызывает нужную операцию. Выбор POST не создаёт задачу в нашем учебном примере, а слово GET в тексте не читает JSON. Пока мы только определяем просьбу клиента.`}),(0,g.jsx)(`p`,{children:`Представим библиотечный каталог. Один и тот же читатель может попросить показать список книг или передать заявку на новую запись. Предмет разговора похож, но намерение различается. В этой аналогии метод похож на тип просьбы, а не на название полки. Граница сравнения проста: реальный сервер проверяет HTTP-договор, а не догадается о действии по бытовому сюжету.`}),(0,g.jsx)(`p`,{children:`Сначала читаем действие обычными словами: получить список, найти одну задачу, создать новую, заменить изменяемую форму целиком, передать часть изменений или удалить задачу. Только после этого соотносим намерение с методом. Английское название может подсказать ассоциацию, но решает договор и ожидаемое изменение состояния.`}),(0,g.jsx)(h,{question:`Что в request выражает намерение клиента, а что в response сообщает о результате?`,hint:`Вспомним форму сообщения из прошлого занятия.`,answer:(0,g.jsx)(`p`,{children:`Метод сообщает намерение в request. Статус и тело находятся в response и описывают результат обработки. Например, POST может попросить создать задачу, а статус 201 сообщает об успешном создании по договору Planner.`})})]}),(0,g.jsxs)(o,{number:`02`,title:`GET: читаем текущее представление`,children:[(0,g.jsx)(a,{children:`GET просит сервер вернуть данные. По назначению это чтение, а не команда изменить задачу.`}),(0,g.jsx)(`p`,{children:`Для Planner чтение списка и чтение одной задачи имеют один метод GET. Количество найденных записей не меняет намерение клиента. Список может содержать много задач, одну задачу или ни одной. Пустой результат списка всё ещё является результатом чтения, а не просьбой создать запись.`}),(0,g.jsx)(`p`,{children:`Безопасный метод в HTTP означает, что клиент не просит изменить предметное состояние. Это не значит, что запрос защищён паролем, что сервер вообще не выполняет никакую техническую работу или что данные никогда не меняются между ответами. Пока клиент ждёт, другой запрос может изменить задачу, поэтому два чтения в разное время могут вернуть разные значения.`}),(0,g.jsx)(`p`,{children:`Вернёмся к каталогу библиотеки. Мы можем открыть карточку и посмотреть название, не переписывая книгу на полке. Это помогает отделить чтение от изменения. Аналогия не описывает доступы, журналирование и все внутренние действия сервера; она показывает только намерение не менять задачу.`}),(0,g.jsx)(`p`,{children:`Проверим формулировку: если мы читаем список, но в нём нет задач, запрос остаётся GET. Если после чтения сервер пометил первую задачу выполненной, такое поведение противоречит роли чтения в нашем договоре. Слово «безопасный» относится к запрошенному эффекту, а не обещает, что вообще никакое состояние приложения никогда не изменится.`}),(0,g.jsx)(s,{statement:`Если список задач пуст, чтение списка перестаёт быть GET, потому что серверу нечего возвращать.`,isTrue:!1,explanation:`Мы всё ещё просим прочитать коллекцию. Пустой список является возможным результатом чтения, а не новым намерением.`}),(0,g.jsx)(`p`,{children:`Путь к операции будет важен для точной формы ответа: список и одна задача являются разными адресуемыми ресурсами. Сейчас мы не строим URL и не выбираем адрес. Сохраняем только вывод о намерении: оба чтения остаются GET.`})]}),(0,g.jsxs)(o,{number:`03`,title:`POST: просим создать задачу`,children:[(0,g.jsx)(a,{children:`В договоре Planner POST передаёт данные для создания новой задачи.`}),(0,g.jsx)(`p`,{children:`Клиент сообщает начальные поля задачи. Сервер проверяет данные, поручает создание существующему сервису и назначает задаче id. Клиент не выбирает этот id и не добавляет готовую запись прямо в JSON. Успешный ответ может содержать созданную задачу; в нашем договоре он сообщает об успешном создании статусом 201.`}),(0,g.jsx)(`p`,{children:`Наличие тела запроса ещё не доказывает, что запись появилась. Сервер может отклонить данные или столкнуться с ошибкой. Поэтому мы различаем намерение клиента и факт результата: POST просит создать, а ответ показывает, что произошло. Статус 201 не является частью метода и не появляется автоматически от одного слова POST.`}),(0,g.jsx)(`p`,{children:`Повтор создания особенно важно оценивать осторожно. Если первый ответ потерялся, клиент не знает, сохранил ли сервер задачу. Повторный POST в нашем договоре может создать ещё одну задачу. Отсутствие ответа не доказывает, что первая попытка не сработала. Здесь мы не проектируем защиту от повторов и не добавляем специальные ключи.`}),(0,g.jsx)(`p`,{children:`Сравним это с оформлением новой библиотечной карточки: второй экземпляр одной заявки может породить вторую запись. Это лишь аналогия риска дубликата. Конкретное поведение определяет API, а не бытовая ситуация и не универсальное правило для всех действий POST.`}),(0,g.jsx)(l,{question:`Мы передали корректные данные для новой задачи. Какой метод соответствует намерению создать её в договоре Planner?`,options:[`GET`,`POST`,`DELETE`],correctIndex:1,explanation:`POST передаёт данные для создания. Успех проверяем по response; сам метод не гарантирует, что запись сохранена.`}),(0,g.jsx)(`p`,{children:`Мы не путаем создание с изменением уже выбранной задачи. У новой задачи ещё нет клиентского id, тогда как обновление сохраняет идентичность существующей записи. Это различие понадобится, когда сравним полную замену и частичное изменение.`})]}),(0,g.jsxs)(o,{number:`04`,title:`PUT: задаём полную изменяемую форму`,children:[(0,g.jsx)(a,{children:`PUT в Planner означает: сделать изменяемые поля существующей задачи такими, какими их передал клиент.`}),(0,g.jsx)(`p`,{children:`Полная форма Planner состоит из title, priority и is_done. При замене сервер сохраняет прежний id и существующие tags, а обновляет всю эту изменяемую часть. Поэтому переданных только title и priority недостаточно для полного PUT по нашему договору. Если клиент намерен изменить лишь заголовок, он должен сообщить об этом как о частичном изменении, а не оставлять остальную форму случайной.`}),(0,g.jsx)(`p`,{children:`До операции задача могла иметь title «Повторить тему», priority 2 и is_done false. После PUT с полной формой «Подготовить разбор», priority 4 и is_done true эти три изменяемых поля получают новые значения. Идентификатор задачи не превращается в новый, а не переданные клиенту tags не становятся частью этой формы.`}),(0,g.jsx)(`p`,{children:`Здесь полезно сравнить PUT с заменой всей карточки настроек на столе. Мы заранее переписываем все изменяемые строки карточки, даже если часть значений остаётся такой же. Это помогает увидеть разницу с правкой одного поля. Но серверный контракт точнее аналогии: он перечисляет обязательные поля и определяет, какие данные сохраняются отдельно.`}),(0,g.jsx)(`p`,{children:`Если повторить ту же полную форму для той же задачи, её итоговые изменяемые поля останутся такими же. Это называют идемпотентностью эффекта: повтор не накапливает ещё одно изменение поверх предыдущего. Идемпотентность сравнивает состояние ресурса, а не требует побайтно одинаковых ответов. В этом разборе мы повторяем запрос к той же задаче и сравниваем только её состояние.`}),(0,g.jsx)(c,{question:`Одна задача имеет title «План», priority 2 и is_done true. Нужно снять отметку и сохранить остальные поля. Какой запрос передаёт только нужное изменение?`,left:{title:`Передать полную форму`,code:`PUT { "title": "План", "priority": 2, "is_done": false }`,note:`PUT передаёт всю изменяемую форму и задаёт все три поля целиком.`},right:{title:`Передать одно изменение`,code:`PATCH { "is_done": false }`,note:`PATCH передаёт только флаг; title и priority остаются прежними.`},preferred:`right`,explanation:`Оба запроса могут дать эти значения, если в PUT передана полная форма. Но для изменения одного флага PATCH сообщает только нужное изменение, а PUT задаёт все изменяемые поля.`}),(0,g.jsx)(`p`,{children:`Оба способа могут привести к одному видимому состоянию, если полная форма передана без ошибок. Различается не только число полей, но и обещание клиенту: PUT задаёт целую изменяемую форму, PATCH сообщает лишь выбранные изменения. Неполный PUT мы не переосмысливаем как PATCH автоматически.`})]}),(0,g.jsxs)(o,{number:`05`,title:`PATCH: меняем часть, остальное сохраняем`,children:[(0,g.jsx)(a,{children:`PATCH в Planner передаёт одно или несколько полей, которые нужно изменить.`}),(0,g.jsx)(`p`,{children:`Сначала смотрим на задачу до запроса, затем на переданные поля и после запроса проверяем весь результат. Если клиент передал только новый title, priority и is_done должны остаться прежними. Если передал несколько полей, меняются только они. Так частичное обновление не превращается в создание новой задачи или в замену всей формы.`}),(0,g.jsx)(`p`,{children:`Представим лист настроек из трёх строк. PUT переписывает всю изменяемую карточку, а PATCH исправляет только отмеченную строку. Если мы меняем флажок, две соседние настройки остаются на месте. Аналогия помогает увидеть сохранение невыбранных полей; в API сами поля и правила задаёт договор Planner.`}),(0,g.jsx)(m,{caption:`Один PATCH сохраняет не переданные поля`,children:(0,g.jsxs)(p,{label:`Состояние задачи до запроса, изменение и состояние после`,children:[(0,g.jsxs)(d,{title:`До запроса`,children:[(0,g.jsx)(`p`,{children:`title: «План»`}),(0,g.jsx)(`p`,{children:`priority: 2`}),(0,g.jsx)(`p`,{children:`is_done: true`})]}),(0,g.jsx)(f,{label:`PATCH передаёт is_done: false`}),(0,g.jsxs)(d,{title:`После запроса`,children:[(0,g.jsx)(`p`,{children:`title: «План»`}),(0,g.jsx)(`p`,{children:`priority: 2`}),(0,g.jsx)(`p`,{children:`is_done: false`})]})]})}),(0,g.jsx)(`p`,{children:`Читаем схему слева направо: запрос меняет только is_done, а title и priority сохраняют прежние значения. На узком экране общая схема выстраивается вертикально, смысл перехода остаётся тем же. Здесь не разбираем, как HTTP-тело различает пропуск поля и null; это отдельная тема позднее.`}),(0,g.jsx)(`p`,{children:`Значение false тоже может быть нужным изменением. Если проверять только истинность значения, такой запрос потеряет команду снять отметку. Поэтому мы рассуждаем о переданном значении и намерении, а не о том, выглядит ли оно как «положительный» ответ.`}),(0,g.jsx)(n,{code:`if values.get("is_done"):
    changes["is_done"] = values["is_done"]`,question:`Почему этот фрагмент пропустит запрос, в котором нужно изменить is_done с true на false?`,options:[`Потому что false означает, что ключ is_done отсутствует`,`Потому что условие проверяет истинность значения и не входит в блок при false`,`Потому что PATCH может менять только строковые поля`],correctIndex:1,explanation:`Ключ может присутствовать со значением false. Условие по истинности проверяет значение, а не факт нужного изменения.`,fix:`if "is_done" in values:
    changes["is_done"] = values["is_done"]`}),(0,g.jsx)(`p`,{children:`Мы не утверждаем, что любой PATCH идемпотентен или что ни один PATCH не может быть идемпотентным. Повторная установка is_done в false оставляет тот же итог, а операция «увеличить priority на один» при каждом повторе дала бы новый итог. Важен смысл конкретного изменения.`})]}),(0,g.jsxs)(o,{number:`06`,title:`DELETE: просим убрать выбранную задачу`,children:[(0,g.jsx)(a,{children:`DELETE просит удалить выбранный ресурс из доступного состояния Planner.`}),(0,g.jsx)(`p`,{children:`В этой модели успешный DELETE возвращает статус 204 без тела, а новый поиск не находит задачу. Метод описывает просьбу, status и body сообщают результат попытки.`}),(0,g.jsx)(`p`,{children:`Если повторно обратиться к уже удалённой задаче, сервер может ответить 404. Это не обязательно отменяет идемпотентность эффекта: после одного удаления и после повторного задача одинаково отсутствует. Сравниваем состояние ресурса, а не требуем одинакового статуса на каждом запросе.`}),(0,g.jsx)(`p`,{children:`Можно представить, что мы убрали запись из списка покупок, а затем проверили, осталась ли она. При повторном удалении запись не исчезает второй раз и список остаётся в том же состоянии. Эта аналогия показывает эффект повтора, но не диктует, каким статусом сервер обязан описать каждую попытку в нашем договоре.`}),(0,g.jsx)(s,{statement:`Если первый DELETE ответил 204, а повторный ответил 404, итоговое состояние задачи после двух запросов не идемпотентно.`,isTrue:!1,explanation:`После первого и повторного запроса задача отсутствует. Статусы различаются, но итоговый эффект удаления не накопился.`}),(0,g.jsx)(`p`,{children:`DELETE не означает «вернуть словарь со словом deleted». Форму успеха задаёт response: в Planner это пустое тело со статусом 204. Метод сообщает намерение, а статус и тело описывают результат. Если первый ответ потерялся, повтор всё равно требует внимательного чтения ответа, но состояние можно проверить отдельным чтением.`})]}),(0,g.jsxs)(o,{number:`07`,title:`Безопасность и идемпотентность отвечают на разные вопросы`,children:[(0,g.jsx)(a,{children:`Безопасность по назначению спрашивает, просит ли метод изменить состояние. Идемпотентность спрашивает, меняется ли итог при повторе.`}),(0,g.jsx)(`p`,{children:`Не смешиваем эти свойства с безопасностью доступа и с одинаковыми ответами. Защищённый доступ решает, кто может отправить запрос. Статус описывает отдельный результат. Безопасный метод не просит изменить предметные данные, а идемпотентный эффект означает, что один и несколько одинаковых запросов оставляют ресурс в одном и том же итоговом состоянии.`}),(0,g.jsx)(`p`,{children:`Для методов нашего курса полезно держать в голове два отдельных вопроса. GET предназначен для чтения и его повтор не меняет данные по запросу. POST создаёт задачу, и повтор может дать ещё одну. PUT устанавливает полную форму, а DELETE добивается отсутствия задачи; повторение этих намерений не должно добавлять новое изменение к прежнему эффекту. PATCH оцениваем по переданной операции, а не только по названию метода.`}),(0,g.jsx)(t,{rows:[[`Вопрос о безопасности`,`Просит ли клиент только прочитать данные или изменить предметное состояние?`],[`Вопрос об идемпотентности`,`Останется ли итоговое состояние тем же после повторения того же запроса?`],[`Вопрос об ответе`,`Какой статус и какое тело вернул сервер в этой конкретной попытке?`]]}),(0,g.jsx)(`p`,{children:`Три вопроса независимы. В Planner повтор DELETE может сохранить отсутствие задачи и при этом получить другой статус. Один статус нельзя использовать как замену проверке состояния. А если PATCH передаёт значение, которое устанавливает поле в определённое состояние, повтор может быть идемпотентным; если команда каждый раз прибавляет единицу, повтор даст другой итог.`}),(0,g.jsx)(`p`,{children:`В этой теме мы классифицируем намерения только для известного договора Planner. Мы не делаем вывод обо всех возможных API по одному примеру и не реализуем автоматически повторы сетевых запросов. Для выбора метода достаточно понимать, какое состояние было до операции, что клиент просит и какие поля должны измениться после неё.`}),(0,g.jsx)(l,{question:`Какие два DELETE-запроса лучше описать как идемпотентные по эффекту?`,options:[`Один удаляет задачу, повторный тоже оставляет её удалённой`,`Первый удаляет задачу, повторный создаёт её заново`,`Первый удаляет задачу, повторный удаляет соседнюю`],correctIndex:0,explanation:`Сравниваем итоговое состояние выбранной задачи после одного и нескольких одинаковых запросов. Достаточно совпадения эффекта, статус ответа может отличаться.`})]}),(0,g.jsxs)(o,{number:`08`,title:`Что мы будем делать в практике`,children:[(0,g.jsx)(a,{children:`Теперь самостоятельно построим соответствие действий и методов и проверим, можем ли объяснить его на состояниях задачи.`}),(0,g.jsx)(u,{variant:`connected`,items:[{title:`Восстановим соответствие`,description:`Мы сопоставим list, get, create, replace, update и delete с методами, которые подходят их намерению.`},{title:`Сравним два состояния задачи`,description:`До изменения title равен «План», priority равен 2, is_done равен true. После PATCH меняется только is_done на false; title и priority сохраняются. PUT задаёт всю изменяемую форму.`},{title:`Проверим смысл повтора`,description:`После первого DELETE задача отсутствует и ответ может иметь статус 204. Повтор может вернуть 404, но задача остаётся отсутствующей.`}]}),(0,g.jsx)(`p`,{children:`В редакторе самостоятельно напишите solve(action): создайте словарь methods для шести допустимых действий list, get, create, replace, update и delete и верните соответствующую строку метода в верхнем регистре. Ничего не печатайте. После автопроверки объясните на примере, почему replace соответствует PUT, а update — PATCH. Затем предскажите состояние одной задачи после DELETE и его повтора: задача остаётся удалённой, даже если ответы отличаются.`}),(0,g.jsx)(`p`,{children:`Следующему занятию передадим готовую таблицу методов. Там мы соединим намерение с адресом и различим четыре шаблона: коллекцию задач, одну задачу, проверку приложения и общую статистику. Сейчас URL, path, сетевой вызов и реальные ответы не строим; результат этого шага состоит в ясном выборе метода и объяснении его ожидаемого эффекта.`})]})]})}export{_ as Lesson43};